import { gunzipSync } from 'node:zlib';
import { readFile, writeFile } from 'node:fs/promises';

const decode = (value) => gunzipSync(Buffer.from(value, 'base64')).toString('utf8');

const createControls = decode('');
const createCss = decode('');
const previewScript = decode('');

await writeFile('src/create-controls.jsx', createControls);
await writeFile('src/create-workspace-v2.css', createCss);
await writeFile('scripts/capture-ui-preview.mjs', previewScript);

const mainPath = 'src/main.jsx';
let main = await readFile(mainPath, 'utf8');

if (!main.includes('Video, Grid2X2')) {
  main = main.replace(
    'Maximize2, LoaderCircle, Trash2, Download, Video',
    'Maximize2, LoaderCircle, Trash2, Download, Video, Grid2X2',
  );
}

const oldNav = `<nav className="nav-group primary-nav">{navPrimary.map(([Icon, label]) => <NavItem key={label} icon={Icon} label={label} active={section === label} onClick={() => { setSection(label); setMobileNav(false); }} />)}</nav>`;
const newNav = `<nav className="nav-group primary-nav">
          {navPrimary.map(([Icon, label]) => <NavItem
            key={label}
            icon={Icon}
            label={label}
            active={section === label && !(label === 'Create' && mode === 'More')}
            onClick={() => {
              if (label === 'Create' && mode === 'More') setMode('Image');
              setSection(label);
              setMobileNav(false);
            }}
          />)}
          <NavItem
            icon={Grid2X2}
            label="More"
            active={section === 'Create' && mode === 'More'}
            onClick={() => { setMode('More'); setSection('Create'); setMobileNav(false); }}
          />
        </nav>`;

if (main.includes(oldNav)) main = main.replace(oldNav, newNav);
else if (!main.includes('label="More"')) throw new Error('Unable to locate primary nav for More insertion');

await writeFile(mainPath, main);
console.log('Applied centered Create evolution, persistent settings, video controls, inline references, and More sidebar.');
